-- CreateTable
CREATE TABLE "collection_items" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "cardId" TEXT NOT NULL,
    "ownedCount" INTEGER NOT NULL DEFAULT 0,
    "wanted" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "collection_items_pkey" PRIMARY KEY ("id")
);

-- ownedCount is an integer copy count. 0 means not owned. The API deletes the
-- row when ownedCount is 0 and wanted is false, so an empty row is not stored.
ALTER TABLE "collection_items"
  ADD CONSTRAINT "collection_items_owned_count_range_check"
  CHECK ("ownedCount" >= 0 AND "ownedCount" <= 99);

